function previewPreset(){const c=presetData[document.querySelector('#presetCountry').value],os=document.querySelector('#presetOs').value,use=document.querySelector('#presetUse').value,browser=document.querySelector('#presetBrowser').value;document.querySelector('#presetTitle').textContent=`${c.name} · ${osNames[os]} · ${useNames[use]} · ${browserNames[browser].replace('Google ','').replace('Microsoft ','').replace('Mozilla ','')}`;document.querySelector('#presetMeta').textContent=`${c.lang.split(' · ')[0]} / ${c.zone} / ${c.size} / 稳定版`}
document.querySelectorAll('#presetCountry,#presetOs,#presetUse,#presetBrowser').forEach(x=>x.addEventListener('change',previewPreset));
document.querySelector('#applyPreset').onclick=()=>{const c=presetData[document.querySelector('#presetCountry').value],os=document.querySelector('#presetOs').value,browser=document.querySelector('#presetBrowser').value;document.querySelector('#browserLanguage').value=c.lang;document.querySelector('#windowSize').value=c.size;const platform=os==='mac'?'macOS':(os==='ubuntu'?'Linux':'Windows');const product=browser==='firefox'?'Mozilla Firefox':(browser==='edge'?'Microsoft Edge':'Google Chrome');document.querySelector('#userAgent').value=`${product} · ${platform}`;document.querySelector('#browserVersion').value='稳定版 · 自动更新';document.querySelector('#windowPosition').value='居中';previewPreset();showToast('快速预设已应用，参数保持一致')};
const browserPreview=document.querySelector('#browserPreview');document.addEventListener('click',e=>{const start=e.target.closest('[data-action="start"]');if(!start)return;const index=Number(start.closest('tr')?.dataset.index),browserKey=environments[index]?.config?.browser||'chrome';if(kernelState[browserKey])setTimeout(()=>browserPreview.classList.add('show'),650)});document.querySelector('#closeBrowserPreview').onclick=()=>browserPreview.classList.remove('show');document.querySelectorAll('[data-browser-tab]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-browser-tab]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.querySelector('#workspacePane').classList.toggle('hidden',btn.dataset.browserTab!=='workspace');document.querySelector('#googlePane').classList.toggle('hidden',btn.dataset.browserTab!=='google')});
const proxyModal=document.querySelector('#proxyImportModal');document.querySelector('#openProxyImport').onclick=()=>proxyModal.classList.add('show');['closeProxyImport','cancelProxyImport'].forEach(id=>document.querySelector('#'+id).onclick=()=>proxyModal.classList.remove('show'));document.querySelectorAll('[data-proxy-tab]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-proxy-tab]').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');document.querySelectorAll('[data-pane]').forEach(x=>x.classList.toggle('hidden',x.dataset.pane!==btn.dataset.proxyTab))});document.querySelector('#parseProxyImport').onclick=()=>{const tab=document.querySelector('[data-proxy-tab].selected').dataset.proxyTab,pane=document.querySelector(`[data-pane="${tab}"]`),inputs=[...pane.querySelectorAll('input,select,textarea')],nodes=[];if(tab==='clash'){const yaml=inputs.find(x=>x.tagName==='TEXTAREA')?.value||'',names=[...yaml.matchAll(/(?:^|\n)\s*-?\s*name\s*:\s*["']?([^\n"']+)/gi)].map(x=>x[1].trim());(names.length?names:['Clash 节点']).forEach((name,i)=>nodes.push({name,type:'clash',server:'订阅节点',port:String(i+1)}))}else if(tab==='http'){const protocol=inputs[0].value,name=inputs[1].value.trim()||`${protocol} 代理`,server=inputs[2].value.trim()||'未填写地址',port=inputs[3].value.trim()||'—';nodes.push({name,type:protocol.toLowerCase(),server,port})}else{const name=inputs[0].value.trim()||'链式代理',server=inputs[3].value.trim()||'第一层 → 第二层',port=inputs[4].value.trim()||'自动';nodes.push({name,type:'chain',server,port})}importedClashNodes.splice(0,importedClashNodes.length,...nodes);syncImportedProxyOptions();renderProxyNodes(nodes);proxyModal.classList.remove('show');showToast(`已导入 ${nodes.length} 个代理，可在新建窗口中选择`)};
